package wgmodern;
import net.minecraft.client.Minecraft;import net.minecraft.client.model.geom.*;import net.minecraft.client.model.geom.builders.*;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.blockentity.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.core.Direction;import net.minecraft.world.item.*;import com.mojang.blaze3d.vertex.*;import com.mojang.math.Axis;
public class LabelRenderer implements BlockEntityRenderer<LabelLibrary.Tile>{
 private static final ResourceLocation TEX=new ResourceLocation("witchinggadgets","textures/models/labellib.png");private static ModelPart model;
 public LabelRenderer(BlockEntityRendererProvider.Context c){}
 private static void box(PartDefinition r,String n,int u,int v,float x,float y,float z,int X,int Y,int Z,boolean mirror){r.addOrReplaceChild(n,CubeListBuilder.create().texOffs(u,v).mirror(mirror).addBox(0,0,0,X,Y,Z),PartPose.offset(x,y,z));}
 public static ModelPart model(){if(model!=null)return model;var mesh=new MeshDefinition();var r=mesh.getRoot();box(r,"top",0,0,-8,0,-8,16,8,16,true);box(r,"base",0,32,-8,12,-8,16,4,16,true);for(int i=0;i<4;i++)box(r,"leg"+i,72,0,i%2==0?-7:3,8,i<2?-7:3,4,4,4,true);box(r,"book0",72,8,-7,16,0,3,8,6,false);box(r,"pages0",72,22,-7,16,1,3,7,5,false);box(r,"book1",90,8,1,16.0001f,-7,6,3,8,false);box(r,"pages1",90,19,2,16.0001f,-6.5f,5,3,7,false);return model=LayerDefinition.create(mesh,128,64).bakeRoot();}
 public static void draw(LabelLibrary.Tile tile,Direction face,PoseStack pose,MultiBufferSource buffers,int light,int overlay){pose.pushPose();pose.translate(.5,0,.5);pose.mulPose(Axis.YP.rotationDegrees(switch(face){case SOUTH->180;case WEST->90;case EAST->270;default->0;}));model().render(pose,buffers.getBuffer(RenderType.entityCutoutNoCull(TEX)),light,overlay);if(tile!=null){pose.translate(-.375,1,-.4375);pose.scale(.375f,.75f,.375f);pose.mulPose(Axis.XP.rotationDegrees(90));item(tile.getItem(1),tile,pose,buffers,light,overlay);if(!tile.getItem(0).isEmpty()){pose.translate(.875,1.4,0);pose.scale(1,1,.5f);int count=Math.max(1,tile.getItem(0).getCount()/6);for(int i=0;i<count;i++){pose.translate(.5,.5,0);pose.mulPose(Axis.ZP.rotationDegrees(10+i*i));pose.translate(-.5,-.5,-.05);item(tile.getItem(0),tile,pose,buffers,light,overlay);}}}pose.popPose();}
 private static void item(ItemStack s,LabelLibrary.Tile tile,PoseStack pose,MultiBufferSource buffers,int light,int overlay){if(s.isEmpty())return;pose.pushPose();pose.translate(.5,.5,0);Minecraft.getInstance().getItemRenderer().renderStatic(s,ItemDisplayContext.FIXED,light,overlay,pose,buffers,tile.getLevel(),0);pose.popPose();}
 @Override public void render(LabelLibrary.Tile tile,float partial,PoseStack pose,MultiBufferSource buffers,int light,int overlay){draw(tile,tile.getBlockState().getValue(SpinningWheel.FACING),pose,buffers,light,overlay);}
}
